import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),i={name:"docs/versions.md"};function d(s,e,n,c,h,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>A Provider version selects a client schema and its exact Form mappings. It does not publish Forms or establish Host support. Form definition versions, package digests, and Host API versions have their own owners and histories.</p><h2 id="choose-an-installation-or-source-target" tabindex="-1">Choose an installation or source target <a class="header-anchor" href="#choose-an-installation-or-source-target" aria-label="Permalink to &quot;Choose an installation or source target&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Status in this repository</th><th>Host API</th><th>Mappings</th><th>Reference</th></tr></thead><tbody><tr><td><strong>4.1.0</strong></td><td>Registry-published</td><td><code>forms.takoform.com/v1</code></td><td>17 Edge Forms</td><td><a href="/docs/getting-started.html">Getting started</a></td></tr><tr><td><strong>5.0.0</strong></td><td>Source target</td><td><code>forms.takoform.com/v2</code></td><td>13 exact Edge Form URLs</td><td><a href="/docs/provider-host-api-v2-source.html">Provider 5</a></td></tr></tbody></table><p>The <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">Provider release identity ledger</a> records the signed tag, immutable GitHub Release, and Registry readback for 4.1.0. The <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/candidates/provider-v5.0.0.json" target="_blank" rel="noreferrer">5.0.0 descriptor</a> selects the source target; it is not evidence of Registry installation. Check the <a href="https://registry.terraform.io/providers/tako0614/takoform/latest" target="_blank" rel="noreferrer">live Registry listing</a> and exact-version readback before changing a consumer pin.</p><p><strong>Provider 4 state is not automatically translated to Provider 5.</strong> Existing v4 workspaces require a separately planned and verified migration. The default source-built plugin speaks v2; it does not fall back to v1 on a v2 failure.</p><h2 id="provider-4-identity-model" tabindex="-1">Provider 4 identity model <a class="header-anchor" href="#provider-4-identity-model" aria-label="Permalink to &quot;Provider 4 identity model&quot;">​</a></h2><p>Provider 4.1.0 selects the 17-Form Edge publication recorded at <a href="https://github.com/tako0614/takoform-forms/commit/3231633605b737ce5279d7fc020b4780568e7091" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3231633605b737ce5279d7fc020b4780568e7091</code></a>. Its resource state records the exact four-field FormRef: group, kind, <code>definitionVersion</code>, and <code>schemaDigest</code>. The separate package digest identifies package bytes. The <a href="/forms/candidates/edge.forms.takoform.com/candidate-set.json">Embedded Edge candidate snapshot</a> retains <code>publicationStatus: unpublished</code> and is not publication evidence. The linked Core v1.0.1 source is the compatibility checkpoint for this v1 reference, not a description of the v5 plugin.</p><p>Provider 5 instead records one exact publisher Form URL in <code>form_url</code> and uses its own schema and private intent-store contract. Its thirteen mappings and exact definition versions are listed in the Provider 5 reference.</p><h2 id="published-compatibility-history" tabindex="-1">Published compatibility history <a class="header-anchor" href="#published-compatibility-history" aria-label="Permalink to &quot;Published compatibility history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Host API lane</th><th>Compatibility</th></tr></thead><tbody><tr><td><strong>4.1.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>Published minor adding rotating token-file authentication and pending-operation custody; same Form identities as 4.0.0.</td></tr><tr><td><strong>4.0.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>Publisher-selected 17-Form Edge release with static-token configuration.</td></tr><tr><td><strong>3.0.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>Immutable 31-Form aggregate release across eight families.</td></tr><tr><td><strong>2.1.1</strong></td><td><code>forms.takoform.com/v1beta1</code></td><td>Fifteen immutable Edge Form identities in the <a href="/release/provider-form-identities.json">identity ledger</a>.</td></tr><tr><td><strong>2.0.0</strong></td><td>Withdrawn <code>v1alpha2</code> epoch</td><td>Exact-pin recovery and migration history.</td></tr><tr><td><strong>1.0.3</strong></td><td>Withdrawn <code>v1alpha1</code> epoch</td><td>Exact-pin recovery and migration history.</td></tr></tbody></table><p>Read the <a href="/release/migrations/v2-to-v3.html">v2-to-v3 migration boundary</a> for state from a withdrawn epoch and the <a href="/release/migrations/v3-to-v4.html">v3-to-v4 publisher-set boundary</a> before upgrading Provider 3. These boundaries do not perform an automatic migration.</p><p>The immutable v4.1.0 tag contains pre-publication reference wording that calls 4.1.0 a candidate and points to v4.0.0. The current release ledger records the later Registry readback. Those tagged and Registry-rendered bytes remain unchanged; corrected Registry documentation must ship in a new version.</p><p>See <a href="/release/">Release evidence</a> and <a href="/conformance/">Conformance</a> for the scope of the retained receipts and executable checks.</p>',14)])])}const g=t(i,[["render",d]]);export{p as __pageData,g as default};
